/* Minimal conversation presentation: keep the answer visible and detail opt-in. */
.context-indicator { position: relative; width: 28px; height: 28px; flex: none; border: 1px solid var(--border-strong); border-radius: 50%; background: transparent; color: var(--muted); cursor: help; }
.context-indicator span { display: block; width: 9px; height: 9px; margin: auto; border: 1.5px solid currentColor; border-radius: 50%; }
.context-indicator:hover, .context-indicator:focus-visible { color: var(--accent); border-color: var(--accent); }
.context-indicator[data-context-state="over-limit"] { color: var(--danger); border-color: var(--danger); }
.context-indicator[data-context-state="over-limit"] span { border-radius: 2px; transform: rotate(45deg); }
.context-indicator:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; }
#chat-status:empty { display: none; }
#add-menu [data-mode] { justify-content: space-between; }
#add-menu [data-mode]::after { content: ''; width: 7px; height: 7px; border: 1px solid var(--border-strong); border-radius: 50%; }
#add-menu [data-mode].is-selected::after { border-color: var(--accent); background: var(--accent); box-shadow: inset 0 0 0 2px var(--surface); }
.run-terminals .cli-terminal { display: block; }
.run-terminals .cli-terminal > summary { cursor: pointer; list-style-position: inside; padding: 2px 0; color: #f4f4f4; font-size: 11px; }
.run-terminals .cli-terminal > summary:focus-visible, .aven-workspace-tools-artifact-summary:focus-visible { outline: 2px solid var(--focus); outline-offset: 2px; border-radius: 4px; }
.run-terminals .cli-terminal[open] > summary { margin-bottom: 8px; }
.operation-summary { margin: 0; color: var(--muted); }
.aven-workspace-tools-artifact-details { display: grid; gap: 10px; min-width: 0; }
.aven-workspace-tools-artifact-summary { display: flex; align-items: center; gap: 10px; min-width: 0; cursor: pointer; list-style-position: inside; }
.aven-workspace-tools-artifact-summary strong { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.aven-workspace-tools-filename { min-width: 0; margin-left: auto; overflow: hidden; color: var(--muted); font: 10px/1.3 Consolas, "Cascadia Mono", "Courier New", monospace; text-overflow: ellipsis; white-space: nowrap; }
.aven-workspace-tools-artifact-details[open] .aven-workspace-tools-artifact-summary { margin-bottom: 10px; }
.aven-workspace-tools-artifact-details[open] .aven-workspace-tools-card-top { padding-top: 2px; }
.setting-check { min-height: 30px; margin: 8px 0 !important; }
.setting-check input { width: 16px !important; height: 16px; flex: none; accent-color: var(--accent); }
@media (max-width: 540px) {
  .context-indicator { width: 30px; height: 30px; }
  .aven-workspace-tools-artifact-summary { align-items: flex-start; }
  .aven-workspace-tools-filename { max-width: 42%; }
}

